# typed: true
# frozen_string_literal: true

require "html/pipeline"

class TaskList
  # Returns a `Nokogiri::DocumentFragment` object.
  def self.filter(*args)
    Filter.call(*T.unsafe(args))
  end

  # TaskList filter replaces task list item markers (`[ ]` and `[x]`) with
  # checkboxes, marked up with metadata and behavior.
  #
  # This should be run on the HTML generated by the Markdown filter, after the
  # SanitizationFilter.
  #
  # Syntax
  # ------
  #
  # Task list items must be in a list format:
  #
  # ```
  # - [ ] incomplete
  # - [x] complete
  # ```
  #
  # Results
  # -------
  #
  # The following keys are written to the result hash:
  #   :task_list_items - An array of TaskList::Item objects.
  class Filter < HTML::Pipeline::Filter

    Incomplete = "[ ]".freeze
    Complete   = "[x]".freeze

    IncompletePattern = /\[[[:space:]]\]/.freeze # matches all whitespace
    CompletePattern   = /\[[xX]\]/.freeze        # matches any capitalization

    # Pattern used to identify all task list items.
    # Useful when you need iterate over all items.
    ItemPattern = /
      [[:space:]]*                     # optional whitespace prefix
      (                       # checkbox
        #{CompletePattern}|
        #{IncompletePattern}
      )
      (?=[[:space:]])                  # followed by whitespace
    /x

    IncompleteItemPattern = /\s*#{IncompletePattern}(?=\s)/.freeze

    # Pattern to match markdown list prefix in front of the task list item checkbox, for example:
    # - [ ]
    # + [ ]
    # * [ ]
    # 1. [ ]
    ItemPrefixPattern = /(?:\s*[-+*]|(?:\s*\d+\.))/

    # Pattern to match task list item inside html node <li /> or <ol />
    # in a body that is already processed by a markdown filter.
    # List prefix is made optional here although probably it should be removed
    # from this pattern completely. We do not need to match prefix here because markdown filter
    # has already replaced it with html tags <li> or <ol>.
    # Keeping it for now to avoid possible backwards compatibility issues.
    ItemPatternParser = /\A#{ItemPrefixPattern}?#{ItemPattern}/

    # Selects first P tag of an LI, if present
    ItemParaSelector = "./p[1]".freeze

    # Pattern used to extract issue label text into a group
    IssueTextPattern = /
      \s*     # optional whitespace
      (.*?)   # non-eager capturing group for all characters
      \s*     # optional whitespace in the end
      \Z      # match to the end of string
    /x

    # Pattern used for matching issues, including checkbox and title
    TrackedIssuePatternParser = /\A#{ItemPrefixPattern}?#{ItemPattern}#{IssueTextPattern}/

    ItemLinePatternMatcher = /\A\s?([-|+|*]|\d\.){1}\s+\[[xX|\s]\]\s?/

    def self.task_body_contains_task_list_items?(body)
      return false if body.nil?

      body.each_line.any? { |line| line.strip.match? ItemLinePatternMatcher }
    end

    def self.too_many_tasks?(body, limit: 100)
      return false if body.nil?
      return false if body.each_line.count < limit

      seen = 0
      body.each_line.each do |line|
        seen += line.strip.match?(ItemLinePatternMatcher) && 1 || 0
        break if seen > limit
      end

      seen > limit
    end

    def task_list_text_node(node)
      first_child = node.children.first
      if first_child && first_child.text? && first_child.text.blank?
        first_child = first_child.next_sibling
      end
      if first_child && first_child.element? && first_child.node_name == "p"
        first_child = first_child.children.first
      end
      return unless first_child && first_child.text?
      return if first_child.text !~ ItemPatternParser

      first_child
    end

    # List of `TaskList::Item` objects that were recognized in the document.
    # This is available in the result hash as `:task_list_items`.
    #
    # Returns an Array of TaskList::Item objects.
    def task_list_items
      result[:task_list_items] ||= []
    end

    def tracked_issue_anchors
      result[:tracked_issue_anchors] ||= []
    end

    # List of alerts references(either text or urls) parsed from document.
    #
    # Returns an Array of GitHub::Goomba::AlertMentionFilter::Item objects.
    def tracked_alert_anchors
      result[:tracked_alert_anchors] ||= []
    end

    # Renders the item checkbox in a span including the item state.
    #
    # Returns a Nokogiri::HTML::DocumentFragment
    def render_item_checkbox(item)
      Nokogiri::HTML.fragment \
        ActionController::Base.helpers.check_box_tag(name = nil, value = nil, checked = item.complete?, disabled: true, class: "task-list-item-checkbox")
    end

    # Public: Marks up the task list item checkbox with metadata and behavior.
    #
    # Returns a Nokogiri::HTML::DocumentFragent
    def render_task_list_item(item, html)
      fragment = render_item_checkbox(item)
      new_text_node = Nokogiri::XML::Text.new(html.sub(ItemPatternParser, ""), fragment)
      fragment << new_text_node
      fragment
    end

    def extract?
      entity.is_a?(Repository)
    end

    # Filters the source for task list items.
    #
    # Each item is wrapped in HTML to identify, style, and layer
    # useful behavior on top of.
    #
    # Modifications apply to the parsed document directly.
    #
    # Returns nothing.
    def filter!
      doc.css("li").reverse_each do |li|
        text_node = task_list_text_node(li)
        next unless text_node

        text = text_node.inner_text.chomp
        match = text.match(ItemPatternParser)
        next unless match

        item = TaskList::Item.new(match[1])
        task_list_items.unshift(item)

        add_css_class(li.parent, "contains-task-list")
        add_css_class(li, "task-list-item")

        if extract?
          match = text.match(TrackedIssuePatternParser)
          if match[2]
            tracked_issue_anchors.unshift(TaskList::TrackedIssueAnchor.new(match[1], match[2]))
          end
        end

        text_node.replace(render_task_list_item(item, text_node.inner_text))
      end
    end

    def call
      filter!
      doc
    end

    # Private: adds a CSS class name to a node, respecting existing class
    # names.
    def add_css_class(node, *new_class_names)
      class_names = (node["class"] || "").split(" ")
      return if new_class_names.all? { |klass| class_names.include?(klass) }
      class_names.concat(new_class_names)
      node["class"] = class_names.uniq.join(" ")
    end
  end
end
